mapper.select:
WITH temp_table AS (
SELECT #{item.embryoCode,jdbcType=VARCHAR} embryo_code, #{item.bomDataVersion,jdbcType=VARCHAR} bom_data_version FROM dual
) select sum(NVL( BAD_NUM, 0 )) as BAD_NUM, EMBRYO_CODE, BOM_DATA_VERSION from T_SAP_EMBRYO_BAD_NUMBER where (embryo_code, bom_data_version) IN ( select embryo_code, bom_data_version from temp_table) and del_flag = '0' AND BAD_DATE BETWEEN to_date(#{badDate,jdbcType=VARCHAR}, 'yyyy-MM' ) AND last_day( to_date(#{badDate,jdbcType=VARCHAR}, 'yyyy-MM' ) ) GROUP BY EMBRYO_CODE, BOM_DATA_VERSION

mapper.update:
merge into T_SAP_EMBRYO_BAD_NUMBER a USING (
select #{ITEM.badDate,jdbcType=DATE} bad_date, #{ITEM.sapCode,jdbcType=VARCHAR} sap_code, #{ITEM.embryoCode,jdbcType=VARCHAR} embryo_code, #{ITEM.badNum,jdbcType=DECIMAL} bad_num, #{ITEM.createBy,jdbcType=VARCHAR} create_by, #{ITEM.createTime,jdbcType=DATE} create_time, #{ITEM.updateBy,jdbcType=VARCHAR} update_by, #{ITEM.updateTime,jdbcType=DATE} update_time, #{ITEM.remark,jdbcType=VARCHAR} remark, #{ITEM.bomDataVersion,jdbcType=VARCHAR} bom_data_version from dual
) b ON ( a.bad_date = b.bad_date and b.sap_code = a.sap_code and b.embryo_code = a.embryo_code and b.bom_data_version = a.bom_data_version AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.bad_num = NVL(b.bad_num, 0), a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.bad_date, a.sap_code, a.embryo_code, a.bad_num, a.create_by, a.create_time, a.remark, a.del_flag, a.bom_data_version) values (T_SAP_EMBRYO_BAD_NUMBER_SEQ.NEXTVAL, b.bad_date, b.sap_code, b.embryo_code, NVL(b.bad_num, 0), b.create_by, sysdate, b.remark, '0', b.bom_data_version)
